/**
 * City and county outlines from the U.S. Census cartographic boundary files
 * (public domain, clipped to the shoreline). Used to place projects that have
 * no coordinates *inside* their city or county, and to sanity-check the
 * coordinates agencies type in.
 *
 * Replaced the Gazetteer "internal points" on 2026-11-20: San Francisco's
 * internal point is about 30 km offshore because its boundary includes the
 * Farallon Islands, which put ~1,700 projects in the Pacific.
 *
 * pipeline/data/boundaries.json is generated by `pnpm --filter
 * @ceqa-atlas/pipeline boundaries` and committed.
 */
import { areaKm2, type BBox, bboxOf, type Shape, simplifyRing } from './geometry.ts';
import type { ShapefileFeature } from './shapefile.ts';

export interface Area {
  name: string;
  bbox: BBox;
  areaKm2: number;
  shape: Shape;
}

export interface Boundaries {
  vintage?: string;
  places: Record<string, Area>;
  counties: Record<string, Area>;
}

/**
 * Normalize a place or county name so CEQAnet's spelling matches the
 * Census's ("City of Redding", "Redding city", "Shasta County").
 */
export function normalizePlaceName(name: string): string {
  return name
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // strip accents (e.g. "Cañada" -> "Canada")
    .toLowerCase()
    .replace(/\(.*?\)/g, ' ')
    .replace(/^(city|town|county) of\s+/, '')
    .replace(/\s+(city|town|cdp|county)$/, '')
    .replace(/\bst\.?\s/g, 'saint ')
    .replace(/\bmt\.?\s/g, 'mount ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** About 30 m at California latitudes: invisible at the zooms we place approximate points. */
const SIMPLIFY_DEGREES = 0.0003;

export function toArea(name: string, shape: Shape): Area | null {
  const simplified = shape
    .map((ring) => simplifyRing(ring, SIMPLIFY_DEGREES).map(([x, y]) => [round5(x), round5(y)] as [number, number]))
    .filter((ring) => ring.length >= 4);
  if (simplified.length === 0) return null;
  return { name, bbox: bboxOf(simplified), areaKm2: Math.round(areaKm2(simplified) * 100) / 100, shape: simplified };
}

function round5(n: number) {
  return Math.round(n * 1e5) / 1e5;
}

/**
 * Build the lookup from Census features. Places: prefer incorporated cities
 * over Census-designated places (CDPs) when two names collide.
 */
export function buildBoundaries(
  places: ShapefileFeature[],
  counties: ShapefileFeature[],
  stateFips = '06',
): Boundaries {
  const index = (features: ShapefileFeature[], isCdp: (f: ShapefileFeature) => boolean) => {
    const out: Record<string, Area> = {};
    const sorted = features
      .filter((f) => f.shape && f.properties.STATEFP === stateFips)
      .sort((a, b) => Number(isCdp(a)) - Number(isCdp(b)));
    for (const f of sorted) {
      const key = normalizePlaceName(f.properties.NAME);
      if (!key || key in out) continue;
      const area = toArea(f.properties.NAME, f.shape!);
      if (area) out[key] = area;
    }
    return out;
  };
  return {
    places: index(places, (f) => f.properties.LSAD === '57'), // 57 = CDP
    counties: index(counties, () => false),
  };
}
